junctionExperiment.command:
@'
import { mkdtemp, mkdir, writeFile, symlink, lstat, stat, realpath, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
const dir = await mkdtemp(path.join(tmpdir(), 'frameforge-junction-probe-'));
try {
  const outside = path.join(dir, 'outside.mp4');
  const link = path.join(dir, 'link.mp4');
  await writeFile(outside, 'real outside export bytes');
  try {
    await symlink(outside, link, 'junction');
    const info = await lstat(link);
    console.log(JSON.stringify({junctionToFile: {symbolicLink: info.isSymbolicLink(), file: info.isFile(), directory: info.isDirectory(), resolved: await realpath(link), targetIsFile: (await stat(link)).isFile(), bytes: String(await readFile(link))}}));
  } catch (error) {
    console.log(JSON.stringify({junctionToFile: {code: error.code, message: error.message}}));
  }
} finally { await rm(dir, {recursive: true, force: true}); }
'@ | node --input-type=module
